B=[a*(6*n+1)*pow(6*n-1,-1,P)%P for n,a in enumerate(A)]
Ai=[1]+[0]*N
for n in range(1,N+1): Ai[n]=-sum(A[i]*Ai[n-i] for i in range(1,n+1))%P
D=conv(B,Ai)
Dp=[[1]+[0]*N]
for k in range(1,11): Dp.append(conv(Dp[-1],D))
LA=[0]*(N+1)
